settings.code:
{% assign shipping-lead-time = product.metafields.customAttributes.shipping-lead-time %}

{% if shipping-lead-time %}

	{% assign lead = shipping-lead-time | split: "-" %}

	{% if lead.size == 2 %}

		{% comment %}
			 calculating  x +days from current date for min and max time 
		{% endcomment %}

		{% assign min-days = lead[0]  | times: 60 | times: 60 | times: 24 %}

        {% capture min_date %} 
        <span class="shipping_lead_date_span">{{ 'now' | date: "%s" | plus: min-days | date: "%e %B %Y" }}</span>
        {% endcapture %}

        {% assign max-days = lead[1]  | times: 60 | times: 60 | times: 24 %}

        {% capture max_date %}
        <span class="shipping_lead_date_span">{{ 'now' | date: "%s" | plus: max-days | date: "%e %B %Y" }}</span>
        {% endcapture %}

        <p class="shipping_lead_date_p">Estimated Ship Date: {{min_date}} - {{max_date}}</p>
	{% endif %}    
{% endif %}
